      "dating_app": {
        "name": "Hinge / Tinder / Bumble",
        "notes": [
          "Move to a date or another app within a few days, chats on apps die fast",
          "Asking for your number or Snap = interest",
          "Deleting the app is a big exclusivity signal"
        ]
      },
      "discord": {
        "name": "Discord",
        "notes": [
          "Inviting you into VC or a small server is like meeting friends",
          "Gaming together counts as quality time"
        ]
      }
